import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

public class Main {
    public static void main(String[] args) throws Exception {
        URI endpoint = URI.create("https://example.com/"); // Replace with an approved API endpoint.
        HttpRequest request = HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(5)).GET().build();
        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        System.out.println("HTTP status: " + response.statusCode());
        if (response.statusCode() >= 200 && response.statusCode() < 300) {
            System.out.println("Response chars: " + response.body().length());
        } else {
            System.out.println("Request failed; do not treat this response as valid data.");
        }
    }
}
